static long feeMinor(long amountMinor, int basisPoints) {
    // 1. scale: cents x basis points, exact in a long for any real payment
    long scaled = amountMinor * basisPoints;
    // 2. divide, keeping the remainder
    long fee = scaled / 10_000, rest = scaled % 10_000;
    // 3. round half-even, the same rule as RoundingMode.HALF_EVEN
    if (rest > 5_000 || (rest == 5_000 && fee % 2 == 1)) fee++;
    return fee;
}

